        if (dy < 0) { PZ_PULL_S = null; pzPullHide(); return; }
        if (Math.abs(dx) > dy) { PZ_PULL_S = null; pzPullHide(); return; }
        if ((window.scrollY || 0) > 1) { PZ_PULL_S = null; pzPullHide(); return; }
