    const gr = await fetch('/api/trial/generate', { method: 'POST', body: fd });
    const gj = await gr.json().catch(() => ({}));
    // (LOTE L2 · FALLBACK HONESTO DE IDIOMA) Igual que en pzGuestSetIg:
