    const _pb = document.getElementById('albumPendientesBtn');
    if (_pb) { if (_pend) _pb.textContent = `⏳ Pendientes de decidir (${_pend})`; _pb.onclick = () => { try { pzSftPendientes(); } catch (e) {} }; }
