  if (!picSrc) { try { const lg = (typeof assetLogo === 'function') ? assetLogo() : null; if (lg && lg.file_path) picSrc = lg.file_path; } catch (e) {} }
  // (LOGO-CABECERA-CLIENTE · Valentino 12/11) Sin foto real ni logo
