  const bioRaw = pzDecEnt(String(P.bio || '')).trim();
  // (REDISEÑO RS-3) La bio que es el título de IG no es una bio: no se muestra.
  const bio = pzIsIgTitleBio(bioRaw) ? '' : bioRaw;
