function pzMesNombre(mes) {
  const ES = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
  const EN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const arr = gzT(ES, EN);
  return arr[((mes - 1) % 12 + 12) % 12] || '';
}
// Informe mensual real (2026-10-26, ítem 5): solo números reales del mes.
// La tarjeta solo existe si el mes tiene al menos un hecho real; en navegación
// a un mes pasado sin hechos se muestra la línea explícita "sin actividad".
function pzInformeMensualHTML(inf, en, explicito) {
  const MES_ES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const MES_EN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const partes = String(inf.mes || '').split('-');
  const nombre = ((en ? MES_EN : MES_ES)[Number(partes[1]) - 1] || '') + ' ' + (partes[0] || '');
  const vacio = !inf.piezas_publicadas && !inf.dias_con_publicacion && !inf.mensajes_capturados && !inf.respuestas_con_ok;
  if (vacio && !explicito) return '';
  const sub = inf.es_mes_actual
    ? (en ? 'Real numbers for ' + nombre + ' · so far' : 'Números reales de ' + nombre + ' · hasta hoy')
    : (en ? 'Real numbers for ' + nombre : 'Números reales de ' + nombre);
  const fila = (n, t, s) => `<div class="pz-informe-fila"><strong>${n}</strong><span>${t}</span>${s ? `<small>${s}</small>` : ''}</div>`;
  const cuerpo = vacio
    ? `<p class="bb-sub">${en ? 'No recorded activity this month.' : 'Sin actividad registrada este mes.'}</p>`
    : `<div class="pz-informe-nums">${fila(inf.piezas_publicadas, en ? 'Posts published' : 'Piezas publicadas', '')}${fila(inf.dias_con_publicacion, en ? 'Days with posts' : 'Días con publicación', en ? 'distinct days with at least one post' : 'días distintos con al menos una pieza')}${fila(inf.mensajes_capturados, en ? 'Customer messages captured' : 'Mensajes de clientes capturados', en ? 'comments and DMs received' : 'comentarios y DMs recibidos')}${fila(inf.respuestas_con_ok, en ? 'Replies with your OK' : 'Respuestas con tu OK', en ? 'sent only after your approval' : 'enviadas solo con tu aprobación')}</div>`;
  const nav = `<div class="pz-informe-nav"><button class="bb-btn bb-btn-ghost" onclick="bbInformeNav(-1)">‹ ${en ? 'Previous month' : 'Mes anterior'}</button>${inf.es_mes_actual ? '' : `<button class="bb-btn bb-btn-ghost" onclick="bbInformeNav(1)">${en ? 'Next month' : 'Mes siguiente'} ›</button>`}</div>`;
  return `<section class="bb-bloque" id="pzInformeMes" data-mes="${esc(inf.mes)}"><h2>${en ? 'Your month with Posty' : 'Tu mes con Posty'}</h2>
    <p class="bb-sub">${sub}</p>
    ${cuerpo}
    ${nav}</section>`;
}
async function bbInformeNav(dir) {
  const sec = document.getElementById('pzInformeMes');
  if (!sec) return;
  const m = /^(\d{4})-(\d{2})$/.exec(sec.getAttribute('data-mes') || '');
  if (!m) return;
  let y = Number(m[1]), mo = Number(m[2]) + dir;
  if (mo < 1) { y -= 1; mo = 12; }
  if (mo > 12) { y += 1; mo = 1; }
  const mes = y + '-' + String(mo).padStart(2, '0');
  try {
    const inf = await api.get('/api/informe-mensual?mes=' + mes);
    if (inf && inf.ok) {
      const tmp = document.createElement('div');
      tmp.innerHTML = pzInformeMensualHTML(inf, (typeof ME !== 'undefined' && ME && ME.lang === 'en'), true);
      if (tmp.firstElementChild) sec.replaceWith(tmp.firstElementChild);
    }
  } catch (e) {}
}

function pzNivelCelebShow(nv, en) {
  const prev = document.getElementById('pzCelebFondo');
  if (prev) { try { prev.remove(); } catch (e) {} }
  const unlock = (en ? 'Level ' : 'Nivel ') + nv.nivel + ': ' + (nv.nombre_nivel || '');
  const div = document.createElement('div');
  div.id = 'pzCelebFondo';
  div.className = 'pz-celeb-fondo';
  document.body.appendChild(div);
  // LOTE 4 — El momento del avance llega solo, sin botón previo; la
  // tarjeta de celebración aparece al terminar (o al tocar X/fondo).
  const hist = Array.isArray(nv.historial) ? nv.historial : [];
  const antes = hist.length > 1 ? hist[hist.length - 2] : null;
  pzMomentoAvanceShow({
    en: en, unlock: unlock, nivel: nv.nivel,
    siguiente: nv.nombre_siguiente ? (en ? 'Next: ' + nv.nombre_siguiente : 'Sigue: ' + nv.nombre_siguiente) : null,
    siguientePremio: null,
    antes: antes,
    onListo: () => { pzCelebTarjetaShow(div, nv, en, unlock); },
  });
}
function pzNivelStoryShow(nv, en) {
  const prev = document.getElementById('pzStoryFondo');
  if (prev) { try { prev.remove(); } catch (e) {} }
  const unlock = (en ? 'Level ' : 'Nivel ') + nv.nivel + ': ' + (nv.nombre_nivel || '');
  const texto = en ? `I leveled up to ${nv.nombre_nivel} with Posty! ${unlock}` : `¡Subí a ${nv.nombre_nivel} con Posty! ${unlock}`;
  const div = document.createElement('div');
  div.id = 'pzStoryFondo';
  div.className = 'pz-celeb-fondo';
  div.innerHTML = `<div class="pz-story" role="dialog" aria-modal="true">
    <button type="button" class="pz-celeb-x" data-pz-story-x aria-label="${en ? 'Close' : 'Cerrar'}">${pzIc("x", 16)}</button>
    <div class="pz-story-card">
      <span class="pz-mg"><img class="pz-story-av" src="ai-avatar.png" alt="Posty"></span>
      <div class="pz-story-big">${esc(en ? `I leveled up to ${nv.nombre_nivel}!` : `¡Subí a ${nv.nombre_nivel}!`)} ${pzIc('gift', 18)}</div>
      <div class="pz-story-unlock">${esc(unlock)}</div>
      <div class="pz-story-firma">posty.</div>
    </div>
    <p class="pz-story-note">${esc(en ? 'Ready for your story — post it from your Instagram whenever you want. Posty never posts alone.' : 'Lista para tu historia — publicala desde tu Instagram cuando quieras. Posty nunca publica solo.')}</p>
    <button type="button" class="pz-celeb-share" data-pz-story-copy>${esc(en ? 'Copy text' : 'Copiar texto')}</button>
    <button type="button" class="pz-celeb-ok" data-pz-story-x>${esc(en ? 'Done' : 'Listo')}</button>
  </div>`;
  document.body.appendChild(div);
  div.addEventListener('click', async (ev) => {
    if (ev.target.closest && ev.target.closest('[data-pz-story-x]')) { try { div.remove(); } catch (e) {} return; }
    const cp = ev.target.closest ? ev.target.closest('[data-pz-story-copy]') : null;
    if (cp) {
      try { await navigator.clipboard.writeText(texto); } catch (e) {
        try { const ta = document.createElement('textarea'); ta.value = texto; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); } catch (e2) {}
      }
      cp.textContent = en ? 'Copied' : 'Copiado';
    }
  });
}
let PZ_NIVEL_PREV = null; // {pct, desafioClave, nivel} de la última tira pintada
function pzNivelToggleDetalle() {
  const strip = document.getElementById('pzNivelStrip');
  const det = document.getElementById('pzNivelDetalle');
  if (!strip || !det) return;
  const open = det.hasAttribute('hidden');
  if (open) det.removeAttribute('hidden'); else det.setAttribute('hidden', '');
  strip.setAttribute('aria-expanded', open ? 'true' : 'false');
  const chev = strip.querySelector('.pz-strip-chev');
  if (chev) chev.innerHTML = open ? pzIc('chevUp', 14) : pzIc('chevDown', 14);
}
function pzMiniFestejoShow(en) {
  try {
    const strip = document.getElementById('pzNivelStrip');
    const col = strip ? strip.querySelector('[data-pz-col]') : null;
    if (!strip || !col || document.getElementById('pzMiniFestejo')) return;
    const div = document.createElement('div');
    div.id = 'pzMiniFestejo';
    div.className = 'pz-mini-festejo';
    div.textContent = en ? 'Challenge done! Posty already learned that.' : '¡Desafío cumplido! Posty ya aprendió eso.';
    col.appendChild(div);
    setTimeout(() => { try { div.remove(); } catch (e) {} }, 4500);
  } catch (e) {}
}
function pzNivelMount() {
  const strip = document.getElementById('pzNivelStrip');
  if (strip && !strip.dataset.pzBound) {
    strip.dataset.pzBound = '1';
    strip.addEventListener('click', (e) => {
      const chip = (e.target && e.target.closest) ? e.target.closest('[data-pz-nivel-accion]') : null;
      if (chip) { location.hash = chip.dataset.pzNivelAccion; return; }
      pzNivelToggleDetalle();
    });
    strip.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      if (e.target && e.target.closest && e.target.closest('[data-pz-nivel-accion]')) return; // el botón nativo dispara el click
      e.preventDefault();
      pzNivelToggleDetalle();
    });
  }
  // Botones del detalle desplegable (negocio + desafio usan data-accion).
  const det = document.getElementById('pzNivelDetalle');
  if (det && !det.dataset.pzBound) {
    det.dataset.pzBound = '1';
    det.addEventListener('click', (e) => {
      const b = (e.target && e.target.closest) ? e.target.closest('[data-pz-nivel-accion]') : null;
      if (b) { location.hash = b.dataset.pzNivelAccion; return; }
    });
  }
  // Llenado en vivo (v469): la barrita arranca donde quedó la última vez y
  // se llena frente al cliente hasta el avance real. Reduced-motion:
  // aparece llena, sin animar. Sin tira no hay nada que animar.
  const reduced = (typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches);
  const fill = strip ? strip.querySelector('[data-pz-fill]') : null;
  const nv0 = (typeof HF_NIVEL !== 'undefined') ? HF_NIVEL : null;
  const target = fill ? Number(fill.getAttribute('data-pz-fill') || 0) : 0;
  const prev = PZ_NIVEL_PREV;
  const from = (prev && prev.pct != null && prev.pct <= target) ? prev.pct : 0;
  if (fill && !reduced && target > from) {
    fill.style.width = from + '%';
    requestAnimationFrame(() => requestAnimationFrame(() => { fill.style.transition = 'width .8s ease'; fill.style.width = target + '%'; }));
  }
  // Mini-festejo por desafío (v469): la clave del desafio cambió sin que el
  // nivel subiera = el reto anterior se completó. Chispa + línea, sin modal.
  if (nv0 && prev && prev.nivel === nv0.nivel && prev.desafioClave && nv0.desafio && nv0.desafio.clave && nv0.desafio.clave !== prev.desafioClave) {
    pzMiniFestejoShow((typeof ME !== 'undefined' && ME && ME.lang === 'en'));
  }
  if (nv0) PZ_NIVEL_PREV = { pct: target, desafioClave: (nv0.desafio && nv0.desafio.clave) || null, nivel: nv0.nivel };
  const desBtn = document.querySelector('[data-pz-desafio-accion]');
  if (desBtn && !desBtn.dataset.pzBound) {
    desBtn.dataset.pzBound = '1';
    desBtn.addEventListener('click', () => { location.hash = desBtn.dataset.pzDesafioAccion; });
  }
  const broteX = document.querySelector('[data-pz-brote-x]');
  if (broteX && !broteX.dataset.pzBound) {
    broteX.dataset.pzBound = '1';
    broteX.addEventListener('click', () => { pzNivelBroteVisto(broteX); const row = document.getElementById('pzNivelBrote'); if (row) row.remove(); });
  }
  const ausX = document.querySelector('[data-pz-ausencia-x]');
  if (ausX && !ausX.dataset.pzBound) {
    ausX.dataset.pzBound = '1';
    ausX.addEventListener('click', () => { const row = document.getElementById('pzNivelAusencia'); if (row) row.remove(); });
  }
  const nv = (typeof HF_NIVEL !== 'undefined') ? HF_NIVEL : null;
  if (!nv || !nv.celebrar || !(nv.nivel > 1)) return;
  const en = (typeof ME !== 'undefined' && ME && ME.lang === 'en');
  const uid = (typeof ME !== 'undefined' && ME && ME.id) ? ME.id : 'x';
  const key = 'pz_nivel_celeb_' + uid + '_' + nv.nivel;
  try { if (localStorage.getItem(key) === '1') return; } catch (e) {}
  try { localStorage.setItem(key, '1'); } catch (e) {}
  try { api.post('/api/oficina/nivel/celebrar', { poder: nv.poder, nivel: nv.nivel }).catch(() => {}); } catch (e) {}
  // (v461) La celebración abre directo: la tira ya no anima evoluciones.
  pzNivelCelebShow(nv, en);
}

function mzOpenSheet(focus) {
  // (LOTE CHATPANTALLA) La hoja se retiró: abrir el chat = navegar a
  // su pantalla. Si ya estamos en ella, foco como siempre.
  if ((location.hash || '').split('?')[0] !== '#/app/chat') { location.hash = '#/app/chat'; return; }
  if (!focus) return;
  // (v846) Sin campo de texto: no hay foco que poner; solo scroll.
  try { chatUpdateSendBtn(); } catch (e) {}
  try { chatScroll(); } catch (e) {}
  try { pzPhStart(); } catch (e) {}
}
// (LOTE SALIR-SIN-ZOOM · 2/11) Antes de retirar/ocultar una hoja,
// soltar el foco: en WKWebView, si el campo enfocado se elimina u
// oculta con el foco puesto, la escala del zoom automático de iOS
// no se restaura y el feed queda con zoom. El blur PRIMERO deja
// que el teclado baje y la escala vuelva; recién después se retira
// la hoja. No-op sin activeElement enfocable.
function pzBlurActivo() {
  try {
    const ae = document.activeElement;
    if (ae && ae.blur && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable)) ae.blur();
  } catch (e) {}
}
function mzCloseSheet() {
  pzBlurActivo();
  const sh = $('#mzSheet');
  if (sh) sh.hidden = true;
  try { document.body.classList.remove('mz-sheet-open'); } catch (e) {}
}
/* ===== (LOTE CHATPANTALLA · 1/11) El chat principal es PANTALLA COMPLETA en vidrio =====
   Reporte de Valentino con captura: al tocar el chat, el teclado tapaba
   todo. Causa: el chat vivía en una hoja sobre Inicio y en la app nativa
   (WKWebView) el teclado NO achica el layout viewport, así que la hoja
   nunca se enteraba. La pantalla nueva: ruta propia (#/app/chat) con la
   transición de siempre, cabecera con Posty + atrás, mensajes con scroll
   interno y campo anclado abajo. La altura la manda el viewport visible
   real (visualViewport, que SÍ se achica con el teclado en WKWebView),
   con fallback a innerHeight. El contenido es EXACTAMENTE el de la hoja
   (mismo chatCardHTML, mismos ids, mismo bindChat): solo cambia el
   contenedor. La hoja se retiró de Inicio; abrir el chat navega acá. */
function chatFullView() {
  const en = (typeof ME !== 'undefined' && ME && ME.lang === 'en');
  // (LOTE CHAT-MUSE) Encabezado FINO estilo Muse: chevron + cara +
  // «Posty.» + punto verde «en línea». Sin tarjeta glass grande.
  return `<div class="pz-chatfull" id="pzChatFull">
  <header class="pz-chatfull-head">
    <button type="button" class="pz-chatfull-back" onclick="pzGoBack()" aria-label="${en ? 'Back' : 'Volver'}">${pzIc('chevronLeft', 22)}</button>
    <img class="chat-face" src="ai-avatar.png" alt="Posty">
    <div class="pz-chatfull-tit"><b>Posty<span class="pdot">.</span></b><span class="pz-chatfull-est" id="pzChatEstado">${en ? 'online' : 'en línea'}</span></div>
    <!-- (CHAT-SIMPLIFICADO v5 · 10/11) Sin compartir ni tuerca en el Chat: quedan atrás, avatar, «Posty.» y «en línea». La tuerca vive en Ajustes; compartir, en el shell de Inicio. -->
  </header>
  ${chatCardHTML(true, true, true, true, true, true, true, true)}
</div>`;
}
// Sincroniza la altura de la pantalla con el viewport visible real.
function pzChatKbSync(esAsentado) {
  const root = document.getElementById('pzChatFull');
  if (!root) return;
  try {
    const vv = window.visualViewport;
    const h = vv ? vv.height : window.innerHeight;
    // (LOTE REDISEÑO R0 · 8/11) El dock de 6 pestañas también está en el
    // chat: el chat termina SOBRE el dock, no lo tapa. Se resta la altura
    // REAL del dock medida en el momento (65–99px según el safe-area:
    // ningún número fijo sirve). Con el teclado abierto el dock queda
    // detrás del teclado y no se resta nada (viewport visible < ventana).
    const kbAbierto = !!(vv && window.innerHeight && (window.innerHeight - vv.height) > 100);
    let dockH = 0;
    if (!kbAbierto) {
      try {
        const dockEl = document.querySelector('.bb-bar') || document.querySelector('.mz-tabs');
        if (dockEl) dockH = Math.ceil(dockEl.getBoundingClientRect().height) || 0;
      } catch (e) {}
    }
    if (h && h > 0) root.style.height = Math.round(h - dockH) + 'px';
    root.style.top = (vv ? Math.round(vv.offsetTop) : 0) + 'px';
    // (LOTE SIMPLIFICAR-APP · PARTE 4 · 9/11: el chat sube y baja con el
    // teclado. El ResizeObserver del pin cubre el resize, pero iOS anima
    // el teclado ~300 ms y el último evento llega antes de que se asiente:
    // al abrir y al cerrar, bajar al final si el pin está prendido (el
    // usuario estaba abajo; si subió a leer, el pin está apagado y no se
    // lo mueve) y re-afirmar tras la animación, para que el último
    // mensaje quede visible arriba del input, sin contenido tapado.
    try { if (typeof PZ_CHAT_PIN !== 'undefined' && PZ_CHAT_PIN) chatScroll(); } catch (e) {}
    if (!esAsentado) {
      try {
        if (!window.__pzChatKbSettle) {
          window.__pzChatKbSettle = true;
          setTimeout(() => {
            try { window.__pzChatKbSettle = false; pzChatKbSync(true); } catch (e) { try { window.__pzChatKbSettle = false; } catch (e2) {} }
          }, 350);
        }
      } catch (e) {}
    }
  } catch (e) {}
}
// Escucha el teclado una sola vez por carga (el sync no hace nada fuera de la pantalla).
function pzChatKbBind() {
  if (window.__pzChatKbBound) return;
  window.__pzChatKbBound = true;
  try {
    const vv = window.visualViewport;
    if (vv) {
      vv.addEventListener('resize', pzChatKbSync);
      vv.addEventListener('scroll', pzChatKbSync);
    }
    window.addEventListener('resize', pzChatKbSync);
    window.addEventListener('orientationchange', pzChatKbSync);
  } catch (e) {}
}
// (LOTE MIC-INICIO) Nota enviada desde Inicio: al abrir el chat, la
// burbuja del usuario (con audio) tiene que estar en el cuadro NUEVO y
// el intercambio correr con ese cuadro — no con el de la hoja oculta.
// Se espera al historial en vuelo: si lo barrió, se repone la burbuja;
// si ya está pintada desde CHAT, solo se le agrega el audio.
function pzVoicePendingDeliver() {
  const p = (typeof window !== 'undefined') ? window.__pzVoicePending : null;
  if (!p || !p.text) return;
  try { window.__pzVoicePending = null; } catch (e) {}
  Promise.resolve(window.__chatHistP).catch(() => {}).then(() => {
    try {
      const box = document.getElementById('chatBox');
      const lastUser = (typeof CHAT !== 'undefined' && CHAT.length) ? CHAT[CHAT.length - 1] : null;
      const pts = Date.now();
      if (!lastUser || lastUser.role !== 'user' || lastUser.text !== p.text) {
        CHAT.push({ role: 'user', text: p.text, ts: pts });
        if (box) { const nb = chatAppendMsg(box, p.audio ? pzVoiceBubbleHTML(p.audio, 0, 'sent', pts) : chatMsgHtml('user', p.text, pts), pts); if (nb && p.audio) { pzVoiceBubbleInit(nb, p.audio, 0); pzVoiceTxAttach(nb, p.text); } }
      } else if (box && p.audio) {
        const bubbles = box.querySelectorAll('.chat-msg.u, .msg-in');
        const lb = bubbles && bubbles.length ? bubbles[bubbles.length - 1] : null;
        if (lb && !lb.querySelector('.vb-player')) { lb.insertAdjacentHTML('beforeend', pzVoicePlayerHTML(p.audio, 0, 'sent')); pzVoiceBubbleInit(lb, p.audio, 0); }
      }
      // (LOTE CHAT-SCROLL) La nota pendiente es un envío: abajo.
      try { chatScroll(true); } catch (e) {}
      chatExchange({ text: p.text, pushed: true });
    } catch (e) {}
  });
}
function bindChatFull() {
  // (v846 · CHAT SOLO POR AUDIO) Sin botón Enviar propio ni input: el
  // prefill todavía no se leyó (si viene un prefill, el chat por temas
  // no se activa).
  try { bindChat(); } catch (e) {}
  try { bindSchedUpload(); } catch (e) {}
  try { pzTemaInit(); } catch (e) {}
  // SACAR-IDEAS (Valentino 3/11): sin píldora Ideas, sin salto a Semana desde ella.
  // Prefill pendiente («Armar otro» desde Semana): el texto lo genera la
  // app, no el cliente — se manda directo, sin campo que rellenar.
  try {
    const pre = sessionStorage.getItem('posty-chat-prefill');
    if (pre) {
      sessionStorage.removeItem('posty-chat-prefill');
      if (document.getElementById('chatBox')) chatSend(pre);
      else { try { sessionStorage.setItem('posty-chat-prefill', pre); } catch (e2) {} }
    }
  } catch (e) {}
  try { chatUpdateSendBtn(); } catch (e) {}
  // (LOTE CHAT-SCROLL) Abrir el chat arranca abajo y el pin se
  // re-afirma mientras se asienta el layout (teclado, imágenes).
  try { pzChatPinArm(); } catch (e) {}
  // Voz pendiente del mic del dock: mismo delay de siempre (80 ms).
  if (window.__pzChatVoice) {
    window.__pzChatVoice = false;
    setTimeout(() => { try { voiceToggle(); } catch (e) {} }, 80);
  }
  // (LOTE MIC-INICIO) Nota enviada desde Inicio: se entrega al abrir el chat.
  try { pzVoicePendingDeliver(); } catch (e) {}
  try { hfPaintAnchor(); } catch (e) {}
  try { hfAnchorRefresh(); } catch (e) {}
  try { pzCambioVozPromptDeliver(); } catch (e) {}
  pzChatKbBind();
  pzChatKbSync();
  pzChatSwipeBind();
  try { pzPhStart(); } catch (e) {}
  // (v846) Sin foco automático al abrir: no hay campo que enfocar; el
  // teclado no se abre solo y el mic queda listo.
}

/* ===== LOTE REDISENO-R6 · CHAT POR TEMAS, ESTILO DESY =====
   El mock (fuente de verdad del diseño) trae el chat como 6ª pestaña
   con UN tema puntual por vez y respuestas cortas para tocar; escribir
   no existe: todo se responde tocando o hablando (v846). El motor real
   cablea esos temas a datos y endpoints reales, nunca al JS demo del
   mock. Orden: (1) el posteo de hoy por aprobar, (2) la pregunta de
   los lunes — solo consultas —, (3) un comentario pendiente con su
   respuesta ya escrita; al final, «Nada pendiente ✓».
   - «Cambialo» NO cierra el tema: pregunta qué cambiar (foto/texto/
     hora), muestra la versión nueva en el chat y avanza solo al
     confirmar («Queda así») o dejarlo para después.
   - La barra de voz queda siempre visible al pie, con la camarita a la
     izquierda y el mic grande a la derecha (solo en #/app/chat).
   - No se activa con ancla hablar-posteo ni con prefill de Editar: ahí
     manda el flujo que ya traía al usuario (el chat único de siempre).
   - Sin tema abierto, chatSend sigue exactamente como siempre: el chat
     libre no se pierde, solo espera a que no haya temas pendientes. */
var PZ_TEMA = null; // { temas: [...], idx: 0, stage: 'topic', cambio: null }
var PZ_TEMA_DESPUES = {}; // temas dejados para después en ESTA sesión
function pzTemaEn() { try { return (typeof ME !== 'undefined' && ME && ME.lang === 'en'); } catch (e) { return false; } }
function pzTemaT(es, en) { return pzTemaEn() ? en : es; }
function pzTemaNorm(s) {
  try { return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); } catch (e) { return String(s || '').toLowerCase(); }
}
function pzTemaHora(scheduledAt) {
  try {
    const tz = (typeof pcTz === 'function') ? pcTz() : undefined;
    return new Intl.DateTimeFormat(pzTemaEn() ? 'en' : 'es', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz }).format(new Date(String(scheduledAt || '')));
  } catch (e) { try { return String(scheduledAt || '').slice(11, 16); } catch (e2) { return ''; } }
}
// Barra del chat completo: Enviar propio + video + frase corta.
// Solo #/app/chat (bindChatFull): las demás superficies conservan su
// barra de siempre (mic que se convierte en enviar, maxlength 2000).
// (v846 · CHAT SOLO POR AUDIO) pzTemaBarraInit murió con la fila de
// escritura: ya no hay botón Enviar propio ni input en el chat
// completo. El mic es siempre mic y los temas se responden
// tocando o hablando.
function pzTemaInit() {
  const root = document.getElementById('pzChatFull');
  if (!root) return;
  // Ancla hablar-posteo o prefill de Editar: manda ese flujo, no temas.
  try {
    if (typeof HF_CHAT_ANCHOR !== 'undefined' && HF_CHAT_ANCHOR && HF_CHAT_ANCHOR.id) return;
    if (sessionStorage.getItem('posty-chat-prefill')) return;
  } catch (e) {}
  const card = document.getElementById('chatCard');
  if (!card || document.getElementById('pzTemaWrap')) return;
  const wrap = document.createElement('div');
  wrap.id = 'pzTemaWrap';
  wrap.setAttribute('aria-live', 'polite');
  root.insertBefore(wrap, card);
  pzTemaCargar();
}
async function pzTemaCargar() {
  const wrap = document.getElementById('pzTemaWrap');
  if (!wrap) return;
  wrap.innerHTML = '<div class="pz-tema"><div class="pz-tema-sub">' + esc(pzTemaT('cargando tus temas…', 'loading your topics…')) + '</div></div>';
  let hoy = null, consultas = null, comentarios = [];
  try { hoy = await api.get('/api/ritual/hoy'); } catch (e) { hoy = null; }
  try { consultas = await api.get('/api/weekly-consultas'); } catch (e) { consultas = null; }
  try { const r = await api.get('/api/comments'); comentarios = (r && r.comments) || []; } catch (e) { comentarios = []; }
  const temas = [];
  // (1) El posteo de hoy, si todavía no está aprobado ni publicado.
  try {
    const card = (hoy && hoy.cartas && hoy.cartas[0]) || (hoy && hoy.recomendada) || null;
    if (card && card.id && !hoy.publicado_hoy && card.approval !== 'approved' && card.approval !== 'auto' && !PZ_TEMA_DESPUES['hoy:' + card.id]) {
      temas.push({ kind: 'hoy', post: card, hora: card.hora_salida || pzTemaHora(card.scheduled_at) });
    }
  } catch (e) {}
  // (2) La pregunta de los lunes: solo si esta semana sigue sin respuesta.
  try {
    if (consultas && consultas.rango == null && consultas.week_key && !PZ_TEMA_DESPUES['lunes:' + consultas.week_key]) {
      temas.push({ kind: 'lunes', week_key: consultas.week_key });
    }
  } catch (e) {}
  // (3) Un comentario pendiente con su respuesta ya escrita.
  try {
    const c = (comentarios || []).find((x) => x && x.id && (x.suggested || '').trim());
    if (c && !PZ_TEMA_DESPUES['comentario:' + c.id]) temas.push({ kind: 'comentario', c });
  } catch (e) {}
  PZ_TEMA = { temas, idx: 0, stage: 'topic', cambio: null };
  pzTemaPintar();
}
function pzTemaActual() {
  if (!PZ_TEMA || !Array.isArray(PZ_TEMA.temas)) return null;
  return PZ_TEMA.temas[PZ_TEMA.idx] || null;
}
