    const meta = pzTemaT('Hoy', 'Today') + (tema.hora ? ' · ' + tema.hora : '') + ' · ' + pzTemaT('Por aprobar', 'To approve');
    // (RS-5 · UN SOLO MENSAJE POR DÍA) El mensaje del día es la tarjeta
