    + '<button type="button" class="pcsheet-opt" data-pz-pc-resched-save>' + pzIc('check', 14) + ' ' + (en ? 'Save new time' : 'Guardar nueva fecha') + '</button>'
    + '<div class="pcsheet-msg pz-pc-resched-msg"></div>'
