  const published = all.filter(p => p.status === 'published');
  const tiles = homeGridCompose({ upcoming, published, recents: ((pzHomeProfGet() || {}).recents || []), ritual: ((typeof PZ_RITUAL_ESTADO !== 'undefined') ? PZ_RITUAL_ESTADO : null), all });
