/* Genera la propuesta de la foto pendiente y la muestra EN EL CHAT.
   Si el usuario escribió algo mientras tanto, ese texto es la visión
   (no se vuelve a preguntar). Token anti-carrera: si el texto cambió
   en medio del fetch, se descarta el resultado viejo y se regenera. */
/* Arma UNA foto pendiente (asegura el asset + POST /armar) SIN rendir
   nada: la tarjeta la rinde pzSftChatProponer y «Aprobar todas» la
   aprueba en silencio. Devuelve {prop} | {gated, pregunta, reason} |
   {busy} | {error}. (LOTE CHAT-CLICKS) */
async function pzSftChatArmarUno(it) {
  const en = pzSftEn();
  if (!(await pzSftAsegurarAssetTmp(it))) return { error: en ? 'I could not upload that photo to the album. Try again.' : 'No pude subir esa foto al álbum. Probá de nuevo.' };
  try {
    const r = await api.post('/api/album/' + it.assetId + '/armar', { vision: it.vision || '' });
    if (!r || (!r.ok && !r.gated && !r.busy)) return { error: en ? 'I could not build the post yet. Tap Other options to decide.' : 'No pude armar el posteo todavía. Tocá Otras opciones para decidir.' };
    if (r.gated) return { gated: true, reason: r.reason || '', pregunta: r.pregunta || null };
    if (r.busy) return { busy: true };
    return { prop: { assetId: it.assetId, postId: r.post_id, scheduled_at: r.scheduled_at, dia: r.dia || '', dia_label: r.dia_label || '', hora: r.hora || '', semana_llena: !!r.semana_llena, caption: r.caption || '', headline: r.headline || '', hashtags: r.hashtags || '', kind: r.kind || 'photo', image_path: r.image_path || it.url || '', thumb: r.thumb || '', hard: r.hard || [], ya_armado: !!r.ya_armado } };
  } catch (e) {
    return { error: en ? 'I could not build the proposal yet. Tap Other options to decide.' : 'No pude armar la propuesta todavía. Tocá Otras opciones para decidir.' };
  }
}
/* Arma UNA foto/video pendiente como EXPRÉS (sin slot de semana): la
   pieza sale HOY si el cliente la acepta con «Publicar hoy». Se usa
   cuando /armar no encuentra hueco libre — el carril exprés no
   necesita slot. (CARRIL EXPRÉS) */
async function pzSftChatArmarExpres(it) {
  const en = pzSftEn();
  if (!(await pzSftAsegurarAssetTmp(it))) return { error: en ? 'I could not upload that photo to the album. Try again.' : 'No pude subir esa foto al álbum. Probá de nuevo.' };
  try {
    const r = await api.post('/api/express/armar', { asset_id: it.assetId, vision: it.vision || '' });
    if (!r || (!r.ok && !r.gated)) return { error: en ? 'I could not build the post yet.' : 'No pude armar el posteo todavía.' };
    if (r.gated) return { gated: true, reason: r.reason || '', pregunta: r.pregunta || null };
    return { prop: { assetId: it.assetId, postId: r.post_id, scheduled_at: null, dia: '', dia_label: '', hora: '', semana_llena: false, caption: r.caption || '', headline: r.headline || '', hashtags: r.hashtags || '', kind: r.kind || 'photo', image_path: r.image_path || it.url || '', thumb: r.thumb || '', expres: true, ya_armado: !!r.ya_armado } };
  } catch (e) {
    return { error: en ? 'I could not build the post yet.' : 'No pude armar el posteo todavía.' };
  }
}
/* (LOTE CHAT-CLICKS · punto 6) UNA sola pregunta con DOS botones cuando
   la foto no muestra el negocio con claridad. La respuesta arma la
   tarjeta (la visión es la opción tocada); nunca dos preguntas seguidas
   y nunca texto libre. El tap NO es un mensaje del chat: no pasa por
   renderChatOptions (que envía el texto). */
var PZ_SFT_PREGUNTA_ACTIVA = null; // {idx} mientras la pregunta está en pantalla
function pzSftChatPregunta(preg) {
  const en = pzSftEn();
  const box = document.getElementById('chatBox');
  if (!box) return;
  try { const old = document.getElementById('pzSftPregunta'); if (old) old.remove(); } catch (e) {}
  const texto = en ? (preg.texto_en || preg.texto) : preg.texto;
  const wrap = document.createElement('div');
  wrap.className = 'chat-msg ai';
  wrap.id = 'pzSftPregunta';
  wrap.style.maxWidth = '100%';
  const q = document.createElement('div');
  q.style.cssText = 'font-size:13px;margin-bottom:8px';
  q.textContent = texto;
  wrap.appendChild(q);
  const chips = document.createElement('div');
  chips.className = 'chat-chips';
  preg.opciones.forEach((op) => {
    const label = (en && op.id === '__material__' && op.label_en) ? op.label_en : op.label;
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.onclick = () => pzSftChatPreguntaResponder(op.id, op.label);
    chips.appendChild(b);
  });
  wrap.appendChild(chips);
  box.appendChild(wrap);
  PZ_SFT_PREGUNTA_ACTIVA = { idx: (PZ_SFT_CHAT_PENDIENTE || {}).idx };
  try { chatScroll(); } catch (e) {}
}
async function pzSftChatPreguntaResponder(opId, label) {
  const pend = PZ_SFT_CHAT_PENDIENTE;
  if (!pend) return;
  const it = pend.items[pend.idx];
  if (!it) return;
  const en = pzSftEn();
  try { const w = document.getElementById('pzSftPregunta'); if (w) w.remove(); } catch (e) {}
  PZ_SFT_PREGUNTA_ACTIVA = null;
  if (opId === '__material__') {
    try {
      if (!it.assetId && it.file) await pzSftAsegurarAssetTmp(it);
      if (it.assetId) await api.post('/api/album/' + it.assetId + '/choice', { choice: 'semana' });
    } catch (e) {}
    it.choice = 'semana';
    pzSftToast(en ? 'Saved as material.' : 'Quedó guardada como material.');
    if (pend.items[pend.idx] === it) pend.idx++;
    pend.preguntadoIdx = -1;
    if (pend.idx < pend.items.length) pzSftChatProponer();
    else if (pend.items.every((x) => x.choice)) PZ_SFT_CHAT_PENDIENTE = null;
    return;
  }
  const vision = 'La foto muestra: ' + label;
  pend.texto = vision;
  it.vision = vision;
  pzSftChatProponer();
}
/* Genera la propuesta de la foto pendiente y la muestra EN EL CHAT.
   Si el usuario escribió algo mientras tanto, ese texto es la visión
   (no se vuelve a preguntar). Token anti-carrera: si el texto cambió
   en medio del fetch, se descarta el resultado viejo y se regenera.
   (LOTE CHAT-CLICKS) La propuesta es una CADENA: arma el ítem actual,
   rinde su tarjeta y sigue con el siguiente — con varias fotos, las
   tarjetas se acumulan (una por foto, huecos consecutivos) y «Aprobar
   todas» las aprueba juntas. La frase fija se dice UNA vez por envío,
   ANTES de la primera tarjeta. */
async function pzSftChatProponer() {
  const pend = PZ_SFT_CHAT_PENDIENTE;
  if (!pend) return;
  if (pend.aprobandoTodas) return;
  const it = pend.items[pend.idx];
  if (!it) return;
  const token = ++pend.token;
  const en = pzSftEn();
  // (LOTE FOTOS-VIDEOS v860 · auditoría #21) Estado honesto mientras se
  // arma: la propuesta tarda (caption por IA) y antes no se veía nada.
  pzSftChatEstadoArmando(pend, it);
  if (pend.texto) it.vision = pend.texto;
  const arm = await pzSftChatArmarUno(it);
  if (PZ_SFT_CHAT_PENDIENTE !== pend) return;
  if (pend.token !== token) { pzSftChatProponer(); return; }
  if (pend.aprobandoTodas) return;
  if (it.choice === 'armar') return; // «Aprobar todas» ya la aprobó mientras se armaba
  if (arm.error) {
    // (CARRIL EXPRÉS) Sin hueco libre en la semana, la pieza igual se
    // arma como exprés (sale hoy si la acepta): el carril exprés no
    // necesita slot. Otros errores (sin IA, etc.) se muestran tal cual.
    if (/No encontré un (día|hueco) libre/i.test(String(arm.error))) {
      const ex = await pzSftChatArmarExpres(it);
      if (PZ_SFT_CHAT_PENDIENTE !== pend) return;
      if (pend.token !== token) { pzSftChatProponer(); return; }
      if (ex.prop) {
        if (!pend.fraseDicha) {
          pend.fraseDicha = true;
          pzSftChatDecir(en ? 'I put together the post for you.' : 'Te armé el posteo.', '');
        }
        pend.propuesta = ex.prop;
        ex.prop.itemIdx = pend.idx;
        PZ_SFT_ARMADO_ACTUAL = ex.prop;
        if (pend.items.length > 1) pzSftChatSemanaAgregar(ex.prop); else pzSftChatTarjetaArmada(ex.prop);
        if (pend.items[pend.idx] === it) pend.idx++;
        if (pend.idx < pend.items.length) pzSftChatProponer();
        return;
      }
      if (ex.gated) {
        if (ex.pregunta && Array.isArray(ex.pregunta.opciones) && ex.pregunta.opciones.length === 2 && pend.preguntadoIdx !== pend.idx) {
          pend.preguntadoIdx = pend.idx;
          pzSftChatPregunta(ex.pregunta);
          return;
        }
        pzSftChatDecir(en ? 'This photo does not show your business clearly enough for an honest proposal. Keep it as material, or write me what it shows.' : 'Esta foto no muestra tu negocio con claridad como para armarte una propuesta honesta. Guardala como material, o escribime qué muestra.', pzSftChatBotones());
        pend.propuesta = null;
        return;
      }
      pzSftChatDecir(ex.error || arm.error, pzSftChatBotones());
      pend.propuesta = null;
      return;
    }
    pzSftChatDecir(arm.error, pzSftChatBotones());
    pend.propuesta = null;
    return;
  }
  if (arm.busy) {
    pzSftChatDecir(en ? 'I am already building that reel — one moment.' : 'Ya estoy armando ese reel, un momento.', pzSftChatBotones());
    pend.propuesta = null;
    return;
  }
  if (arm.gated) {
    // (LOTE CHAT-CLICKS · punto 6) UNA sola pregunta con DOS botones,
    // nunca texto libre; en cuanto responde, se arma la tarjeta. Nunca
    // dos preguntas seguidas: la segunda vez, el mensaje honesto.
    if (arm.pregunta && Array.isArray(arm.pregunta.opciones) && arm.pregunta.opciones.length === 2 && pend.preguntadoIdx !== pend.idx) {
      pend.preguntadoIdx = pend.idx;
      pzSftChatPregunta(arm.pregunta);
      return;
    }
    pzSftChatDecir(en ? 'This photo does not show your business clearly enough for an honest proposal. Keep it as material, or write me what it shows.' : 'Esta foto no muestra tu negocio con claridad como para armarte una propuesta honesta. Guardala como material, o escribime qué muestra.', pzSftChatBotones());
    pend.propuesta = null;
    return;
  }
  pend.propuesta = arm.prop;
  arm.prop.itemIdx = pend.idx;
  PZ_SFT_ARMADO_ACTUAL = arm.prop;
  // (LOTE CHAT-CLICKS · punto 1) La frase fija, UNA vez por envío,
  // ANTES de la primera tarjeta. «De hoy» solo si el posteo sale hoy
  // (el slot nunca es hoy: armarNextFeedSlot arranca mañana).
  if (!pend.fraseDicha) {
    pend.fraseDicha = true;
    const multi = pend.items.length > 1;
    const hoy = !!(arm.prop.dia && arm.prop.dia === pzSftHoyYmd());
    const frase = multi
      ? (en ? 'I put together the posts for you.' : 'Te armé los posteos.')
      : hoy
        ? (en ? "I put together today's post for you." : 'Te armé el posteo de hoy.')
        : (en ? 'I put together the post for you.' : 'Te armé el posteo.');
    pzSftChatDecir(frase, '');
  }
  // (LOTE FOTOS-VIDEOS v860 · opción 5) Con varias fotos, las tarjetas no
  // se acumulan sueltas: van como filas de LA SEMANA en una sola pantalla.
  if (pend.items.length > 1) pzSftChatSemanaAgregar(arm.prop); else pzSftChatTarjetaArmada(arm.prop);
  // La cadena: la siguiente foto se arma sola (hueco libre siguiente).
  if (pend.items[pend.idx] === it) pend.idx++;
  if (pend.idx < pend.items.length) pzSftChatProponer();
}
/* Un toque aprueba: el texto YA se mostró en el chat, así que crear el
   borrador no es un salto a ciegas. Video: se crea con los valores por
   defecto (sin silencios/lenta/ánimo); las opciones de video viven en
   la pantalla de propuesta vía Otras opciones. Gate duro (cortada):
   se transfiere a la pantalla de propuesta para resolverlo ahí.
   (LOTE CHAT-CLICKS) postId: con varias tarjetas, aprueba ESA tarjeta
   (sin postId, la última armada). La cadena arma sola: aprobar ya NO
   avanza la cola. */
async function pzSftChatAprobar(btn, postId) {
  // (LOTE A · ítem 4) El posteo YA está armado (POST /armar en la
  // propuesta): aprobar es la rama draft de siempre — PATCH
  // scheduled_at + señal approved — con el mismo gate de Instagram que
  // pzHoyAprobarUno. Sin /crear: el borrador ya existe.
  const pend = PZ_SFT_CHAT_PENDIENTE;
  const prop = (postId && PZ_SFT_ARMADOS[Number(postId)]) || (pend && pend.propuesta) || PZ_SFT_ARMADO_ACTUAL;
  if (!prop || !prop.postId) return;
  const it = pend ? ((typeof prop.itemIdx === 'number') ? pend.items[prop.itemIdx] : pend.items.find((x) => x.assetId === prop.assetId)) : null;
  if (it && it.choice === 'armar') return; // ya aprobado (doble toque)
  const en = pzSftEn();
  pzSftChatQuitarBotones();
  if ((prop.hard && prop.hard.length)) { pzSftChatOpciones(true); return; }
  if (!(typeof PROFILE !== 'undefined' && PROFILE && PROFILE.ig_connected)) { try { igGateFeedback(btn || document.body); } catch (e) {} return; }
  const okA = await pzSftChatAprobarUno(prop, it);
  if (!okA) { pzSftChatDecir(en ? 'I could not approve it.' : 'No pude aprobarlo.', pzSftChatBotones()); return; }
  pzSftChatMarcarAprobada(prop.postId);
  toast('✅ ' + (en ? 'Scheduled — it goes out on its own' : 'Programado — sale solo'));
  const cuando = (prop.dia_label && prop.hora) ? (en ? `goes out ${prop.dia_label} at ${prop.hora}` : `sale el ${prop.dia_label} a las ${prop.hora}`) : '';
  pzSftChatDecir((en ? `Done! The post ${cuando ? cuando : 'is scheduled'} ✓` : `¡Listo! El posteo ${cuando ? cuando : 'quedó programado'} ✓`),
    "<div id=\"pzSftChatBtns2\" style=\"display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 4px;\"><button type=\"button\" class=\"btn btn-primary btn-sm\" onclick=\"location.hash='#/app/post/" + prop.postId + "'\">" + (en ? "See post" : "Ver posteo") + "</button></div>");
  try { render(); } catch (e) {}
  if (pend && pend.items.every((x) => x.choice)) PZ_SFT_CHAT_PENDIENTE = null;
}
/* (LOTE CHAT-CLICKS) Aprueba UN armado en silencio (sin mensaje):
   PATCH scheduled_at + señal approved + choice 'armar' +
   pzSftGuardarPost. El gate de IG lo chequea el LLAMADOR. */
async function pzSftChatAprobarUno(prop, it) {
  if (!prop || !prop.postId) return false;
  try {
    const w = prop.scheduled_at ? new Date(prop.scheduled_at).toISOString() : null;
    await api.patch('/api/posts/' + encodeURIComponent(prop.postId), { scheduled_at: w });
    try { await api.post('/api/posts/' + encodeURIComponent(prop.postId) + '/signal', { signal: 'approved' }); } catch (e) {}
    try { if (typeof track === 'function') track('draft_accept', { id: Number(prop.postId) }); } catch (e) {}
    try { await api.post('/api/album/' + prop.assetId + '/choice', { choice: 'armar' }); } catch (e) {}
    pzSftGuardarPost(prop.assetId, prop.postId);
    if (it) it.choice = 'armar';
    return true;
  } catch (e) { return false; }
}
/* (LOTE CHAT-CLICKS · punto 3) UN solo botón aprueba todas las fotos
   del envío: las tarjetas ya armadas + las que faltan (se arman en
   orden, en huecos libres consecutivos, y se aprueban). Si una no se
   puede armar, se frena ahí y se muestra su tarjeta/pregunta como
   siempre. */
async function pzSftChatAprobarTodas() {
  const pend = PZ_SFT_CHAT_PENDIENTE;
  if (!pend) return;
  const en = pzSftEn();
  if (!(typeof PROFILE !== 'undefined' && PROFILE && PROFILE.ig_connected)) { try { igGateFeedback(document.body); } catch (e) {} return; }
  pend.aprobandoTodas = true;
  const total = pend.items.length;
  let okN = 0;
  // 1) todas las tarjetas ya armadas
  for (const pid of Object.keys(PZ_SFT_ARMADOS)) {
    const prop = PZ_SFT_ARMADOS[pid]; // (CARRIL EXPRÉS) lo ya publicado hoy no se re-aprueba en semana
    const it = (typeof prop.itemIdx === 'number') ? pend.items[prop.itemIdx] : pend.items.find((x) => x.assetId === prop.assetId);
    if (!it || it.choice === 'armar' || it.choice === 'expres' || it.choice === 'descartado' || it.choice === 'despues') continue;
    if (await pzSftChatAprobarUno(prop, it)) { okN++; pzSftChatMarcarAprobada(prop.postId); }
  }
  pend.propuesta = null;
  // 2) lo que falta armar, en orden
  let fallo = null;
  while (pend.idx < pend.items.length) {
    const it = pend.items[pend.idx];
    if (!it) break;
    if (it.choice === 'armar' || it.choice === 'expres' || it.choice === 'descartado' || it.choice === 'despues') { pend.idx++; continue; } // (LOTE FOTOS-VIDEOS v860) lo descartado o «después» no se re-aprueba ni se re-arma
    pend.preguntadoIdx = -1;
    if (pend.texto) it.vision = pend.texto;
    const arm = await pzSftChatArmarUno(it);
    if (arm.prop) {
      arm.prop.itemIdx = pend.idx;
      PZ_SFT_ARMADO_ACTUAL = arm.prop;
      PZ_SFT_ARMADOS[Number(arm.prop.postId)] = arm.prop;
      if (await pzSftChatAprobarUno(arm.prop, it)) { okN++; pzSftChatMarcarAprobada(arm.prop.postId); pend.idx++; continue; }
      fallo = { error: true };
      break;
    }
    fallo = arm;
    break;
  }
  pend.aprobandoTodas = false;
  try { render(); } catch (e) {}
  // (LOTE FOTOS-VIDEOS v860) Decidido = aprobado, exprés, descartado o
  // «después»: lo descartado no se re-arma ni se cuenta como pendiente.
  const decidido = (x) => x.choice === 'armar' || x.choice === 'expres' || x.choice === 'descartado' || x.choice === 'despues';
  const aprobables = pend.items.filter((x) => x.choice !== 'descartado' && x.choice !== 'despues').length;
  if (!fallo && pend.items.every(decidido)) {
    PZ_SFT_CHAT_PENDIENTE = null;
    if (okN > 0) pzSftChatDecir(en ? `Done! All ${okN} posts scheduled ✓` : `¡Listo! Los ${okN} posteos quedaron programados ✓`, '');
    else pzSftChatDecir(en ? 'Done — nothing left to approve.' : 'Listo — no quedó nada por aprobar.', '');
    return;
  }
  pzSftChatDecir(en ? `I approved ${okN} of ${aprobables} — this one is still pending:` : `Aprobé ${okN} de ${aprobables} — este quedó pendiente:`, '');
  pzSftChatProponer();
}
/* (LOTE CHAT-CLICKS) Marca la tarjeta aprobada EN EL LUGAR (sin
   borrarla): la fila de botones pasa a «✓ Programado». */
function pzSftChatMarcarAprobada(postId) {
  try {
    const row = document.getElementById('pzSftCardBtns-' + Number(postId));
    if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">✓ ' + (pzSftEn() ? 'Scheduled' : 'Programado') + '</span>';
  } catch (e) {}
  // (LOTE FOTOS-VIDEOS v860 · opción 5) La fila de la semana también se marca.
  try {
    const wrow = document.getElementById('pzSftSemanaRow-' + Number(postId));
    if (wrow) { const ch = wrow.lastElementChild; if (ch) { ch.textContent = '✓'; ch.style.color = '#22C55E'; } wrow.style.opacity = '0.75'; }
  } catch (e) {}
}
/* (CARRIL EXPRÉS) «Publicar hoy»: un toque publica la pieza HOY, directo,
   sin 9:00 ni aviso de 30 min y sin cupo. El posteo diario sigue su curso
   y el video del cliente no toca el video semanal. Se consulta el estado
   hasta verlo publicado (mismo patrón que publishNowFlow). */
async function pzSftChatPublicarHoy(postId) {
  const prop = (postId && PZ_SFT_ARMADOS[Number(postId)]) || PZ_SFT_ARMADO_ACTUAL;
  if (!prop || !prop.postId) return;
  const en = pzSftEn();
  const pid = Number(prop.postId);
  if (!(typeof PROFILE !== 'undefined' && PROFILE && PROFILE.ig_connected)) { try { igGateFeedback(document.body); } catch (e) {} return; }
  const row = document.getElementById('pzSftCardBtns-' + pid);
  if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">⏳ ' + (en ? 'Publishing today…' : 'Publicando hoy…') + '</span>';
  let r;
  try { r = await api.post('/api/express/' + pid + '/publicar', {}); }
  catch (e) {
    const msg = (e && e.data && (e.data.message || e.data.error)) || (e && e.message) || '';
    if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">😅 ' + esc(msg || (en ? 'Try again' : 'Probá de nuevo')) + '</span>';
    pzSftChatDecir(msg || (en ? 'I could not publish it.' : 'No pude publicarlo.'), '');
    return;
  }
  if (!r || !r.ok) {
    if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">😅 ' + (en ? 'Try again' : 'Probá de nuevo') + '</span>';
    return;
  }
  const pend = (typeof PZ_SFT_CHAT_PENDIENTE !== 'undefined' && PZ_SFT_CHAT_PENDIENTE) ? PZ_SFT_CHAT_PENDIENTE : null;
  const it = pend ? ((typeof prop.itemIdx === 'number') ? pend.items[prop.itemIdx] : pend.items.find((x) => x.assetId === prop.assetId)) : null;
  if (it) it.choice = 'expres';
  const t0 = Date.now();
  while (Date.now() - t0 < 3.5 * 60 * 1000) {
    await new Promise((res2) => setTimeout(res2, 2500));
    let st;
    try { st = (await api.get('/api/posts/' + pid)).post; } catch (e) { continue; }
    if (!st) continue;
    if (st.status === 'published') {
      pzSftChatMarcarPublicadoHoy(pid, st.ig_permalink);
      toast('🎉 ' + (en ? 'Published today!' : '¡Ya salió hoy!'));
      try { render(); } catch (e) {}
      if (pend && pend.items.every((x) => x.choice)) PZ_SFT_CHAT_PENDIENTE = null;
      return;
    }
    if (st.status === 'failed' || st.status === 'cancelled') {
      if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">😅 ' + esc(st.error || (en ? 'It could not be published.' : 'No se pudo publicar.')) + '</span>';
      return;
    }
  }
  if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">⏳ ' + (en ? 'Still publishing — you will see it in Schedule in a minute.' : 'Sigue publicándose… lo ves en Schedule en un minuto.') + '</span>';
}
/* (CARRIL EXPRÉS) Marca la tarjeta publicada HOY en el lugar, con el link a Instagram. */
function pzSftChatMarcarPublicadoHoy(postId, permalink) {
  try {
    const en = pzSftEn();
    const row = document.getElementById('pzSftCardBtns-' + Number(postId));
    if (row) row.innerHTML = '<span style="font-size:13px;color:var(--mut)">✓ ' + (en ? 'Published today!' : '¡Publicado hoy!') + '</span>' +
      (permalink ? ` <a href="${esc(permalink)}" target="_blank" rel="noopener" style="font-size:13px;color:#2793C8">` + (en ? 'View on Instagram' : 'Ver en Instagram') + '</a>' : '');
    // La línea de «cuándo» queda en pasado: ya salió, no «sale cuando lo aceptes».
    const card = document.getElementById('pzSftCard-' + Number(postId));
    const cuando = card && card.querySelector ? card.querySelector('.pz-sft-cuando') : null;
    if (cuando) cuando.innerHTML = '<b>' + (en ? 'Published today ✓' : 'Salió hoy ✓') + '</b>';
    // (LOTE FOTOS-VIDEOS v860) El chip 📅 es lo que se ve: pasa a «Hoy ✓».
    try { const chip = document.getElementById('pzSftChipCuando-' + Number(postId)); if (chip) chip.textContent = '📅 ' + (en ? 'Today ✓' : 'Hoy ✓'); } catch (e) {}
  } catch (e) {}
}
/* Hoy en la zona del cliente (yyyy-mm-dd), para la frase fija. */
function pzSftHoyYmd() {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
}
// Tarjeta del posteo armado en el chat (Caso 2: foto + fecha + caption
// + aprobar/cambiar — nunca texto volcado). El armado vigente queda en
// PZ_SFT_ARMADO_ACTUAL para «Cambiar texto / Cambiar día».
var PZ_SFT_ARMADO_ACTUAL = null;
var PZ_SFT_ARMADOS = {}; // postId → propuesta armada (varias tarjetas en el chat)
function pzSftChatTarjetaArmada(prop) {
  const en = pzSftEn();
  const box = document.getElementById('chatBox');
  if (!box) { pzSftChatDecir(en ? 'Post ready.' : 'Posteo listo.', pzSftChatBotones()); return; }
  const pid = Number(prop.postId) || 0;
  PZ_SFT_ARMADOS[pid] = prop;
  try { const old = document.getElementById('pzSftCard-' + pid); if (old) old.remove(); } catch (e) {}
  try { pzSftChatQuitarArmando(); } catch (e) {}
  // (LOTE FOTOS-VIDEOS v860 · opción 3) Tarjeta con todo tocable (mock
  // aprobado por Valentino): miniatura 96×120 4:5 a la izquierda + caption
  // (clamp 4, el detalle completo está a un toque) + chips tocables
  // (día·hora / caption / foto·video) + «Sale así» verde. El video se
  // muestra con su primer cuadro (nunca bloque de color): sin portada, el
  // propio <video> hace de miniatura. El botón de aprobar es verde
  // #22C55E (btn-primary es celeste, por eso va inline).
  const esVideo = prop.kind === 'video';
  const media = esVideo && prop.image_path
    ? `<div style="width:96px;height:120px;flex:0 0 96px;border-radius:14px;overflow:hidden;position:relative"><video src="${esc(prop.image_path)}" ${prop.thumb ? `poster="${esc(prop.thumb)}"` : ''} muted playsinline preload="metadata" style="width:100%;height:100%;object-fit:cover;display:block"></video><span style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:30px;height:30px;border-radius:50%;background:rgba(10,30,51,.72);border:2px solid #fff;color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;padding-left:2px">▶</span><span style="position:absolute;left:6px;top:6px;background:rgba(255,255,255,.92);color:#0A1E33;font-size:11px;font-weight:700;padding:3px 7px;border-radius:999px">🎬 Reel</span></div>`
    : (prop.image_path ? `<div style="width:96px;height:120px;flex:0 0 96px;border-radius:14px;overflow:hidden;position:relative"><img class="pz-sft-img" src="${esc(prop.image_path)}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block"><span style="position:absolute;left:6px;top:6px;background:rgba(255,255,255,.92);color:#0A1E33;font-size:11px;font-weight:700;padding:3px 7px;border-radius:999px">📸 Post</span></div>` : '');
  const capCorto = String(prop.caption || '');
  const detalleTxt = esVideo ? (en ? 'Tap the video to see it →' : 'Tocá el video para verlo →') : (en ? 'Tap the photo to see the detail →' : 'Tocá la foto para ver el detalle →');
  // (LOTE FOTOS-VIDEOS v860 · #5) La tarjeta dice que es una PROPUESTA:
  // nada sale hasta «Sale así». Antes decía «Tu posteo está armado» +
  // «Sale el X a las Y» y se leía como ya programado (el 587).
  const titulo = esVideo ? (en ? 'Here is your reel, ready 👇' : 'Acá está tu reel, ya armado 👇') : (en ? 'Here is your post, ready 👇' : 'Acá está tu posteo, ya armado 👇');
  const notaProp = en ? 'This is a draft — nothing goes out until you tap Post it.' : 'Es una propuesta — no sale nada hasta que toques Sale así.';
  const cuando = (prop.dia_label && prop.hora) ? (en ? `Goes out ${prop.dia_label} at ${prop.hora}` : `Sale el ${prop.dia_label} a las ${prop.hora}`) : (prop.expres ? (en ? 'Goes out today when you accept it' : 'Sale hoy cuando lo aceptes') : '');
  const llena = prop.semana_llena ? `<div style="font-size:12px;color:var(--mut);margin-top:4px">${en ? 'This week is full — it goes out next Monday.' : 'Esta semana está completa — sale el lunes que viene.'}</div>` : '';
  // Chips (mock opción 3): día·hora abre días+horas libres; caption pide
  // el cambio por voz; foto abre el picker de fotos guardadas (miniaturas
  // tocables + vista previa + Confirmar). El video no se cambia con
  // usar-foto (solo fotos): el chip avisa honesto cómo cambiarlo.
  const chipCuando = (prop.dia_label && prop.hora)
    ? `<button type="button" id="pzSftChipCuando-${pid}" onclick="pzSftChatCambiarDia(${pid})" style="border:1px solid #2793C8;border-radius:999px;padding:7px 11px;font-size:13px;font-weight:600;background:#EFF8FD;color:#2793C8;cursor:pointer;font-family:inherit">📅 ${esc(prop.dia_label)} · ${esc(prop.hora)}</button>` : '';
  const chipCaption = `<button type="button" onclick="pzCambioVoz(${pid})" style="border:1px solid #d7e3ec;border-radius:999px;padding:7px 11px;font-size:13px;font-weight:600;background:#fff;color:#0A1E33;cursor:pointer;font-family:inherit">✏️ Caption</button>`;
  const chipMedia = esVideo
    ? `<button type="button" onclick="pzSftChatVideoAviso()" style="border:1px solid #d7e3ec;border-radius:999px;padding:7px 11px;font-size:13px;font-weight:600;background:#fff;color:#0A1E33;cursor:pointer;font-family:inherit">🎬 Video</button>`
    : `<button type="button" onclick="pzUsarFotoAbrir(${pid})" style="border:1px solid #d7e3ec;border-radius:999px;padding:7px 11px;font-size:13px;font-weight:600;background:#fff;color:#0A1E33;cursor:pointer;font-family:inherit">🖼️ ${en ? 'Photo' : 'Foto'}</button>`;
  // (LOTE FOTOS-VIDEOS v860) «Sale así» es EL botón de aprobar: verde
  // #22C55E, a lo ancho, primero. «Publicar hoy» (carril exprés) queda
  // segundo: en la tarjeta de semana es blando; en la exprés (sin «Sale
  // así») es el único y va verde. [Cambiar día], [Otra foto], [Usar la
  // foto que envié] y [Cambiar algo] mueren acá: los cubren los chips.
  const saleAsiBtn = prop.expres ? '' : `<button type="button" class="btn btn-sm" style="background:#22C55E;color:#fff;border:none;box-shadow:0 6px 16px rgba(34,197,94,.42);flex:1 1 100%" onclick="pzSftChatAprobar(this, ${pid})">${en ? 'Post it ✓' : 'Sale así ✓'}</button>`;
  const hoyBtn = prop.expres
    ? `<button type="button" class="btn btn-sm" style="background:#22C55E;color:#fff;border:none;box-shadow:0 6px 16px rgba(34,197,94,.42);flex:1 1 100%" onclick="pzSftChatPublicarHoy(${pid})">${en ? 'Publish today' : 'Publicar hoy'}</button>`
    : `<button type="button" class="btn btn-soft btn-sm" onclick="pzSftChatPublicarHoy(${pid})">${en ? 'Publish today' : 'Publicar hoy'}</button>`;
  const descartarBtn = `<button type="button" class="btn btn-ghost btn-sm" onclick="pzSftChatDescartar(${pid})">${en ? 'Discard' : 'Descartar'}</button>`;
  const card = `<div class="chat-msg ai" id="pzSftCard-${pid}" style="max-width:100%;padding:8px"><div style="font-weight:700;font-size:13px;margin-bottom:6px">${esc(titulo)}</div><div style="display:flex;gap:0;cursor:pointer" onclick="location.hash='#/app/post/${pid}'">${media}<div style="flex:1;padding:11px 12px;min-width:0"><div class="pz-sft-cap" style="font-size:13.5px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden">${esc(capCorto)}</div><div style="font-size:12.5px;color:var(--mut);margin-top:6px;font-weight:600">${esc(detalleTxt)}</div></div></div><div style="font-size:12px;color:var(--mut);margin-top:6px">${esc(notaProp)}</div>${prop.hashtags ? `<div style="font-size:12px;color:var(--mut)">${esc(prop.hashtags)}</div>` : ''}${llena}<div class="pz-sft-chips" style="display:flex;gap:7px;flex-wrap:wrap;margin-top:10px">${chipCuando}${chipCaption}${chipMedia}</div><div id="pzSftCardBtns-${pid}" style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">${saleAsiBtn}${hoyBtn}${descartarBtn}</div><div id="pzSftDias-${pid}"></div><div class="pz-sft-cuando" style="display:none">${esc(cuando)}</div></div>`;
  box.insertAdjacentHTML('beforeend', card);
  try { chatScroll(); } catch (e) {}
}
// (LOTE FOTOS-VIDEOS v860 · #21) Burbuja de estado mientras se arma la
// propuesta: nunca espera a ciegas. Se quita al rendir la tarjeta / la
// fila de la semana / al decir cualquier mensaje (pzSftChatDecir).
function pzSftChatEstadoArmando(pend, it) {
  const en = pzSftEn();
  const box = document.getElementById('chatBox');
  if (!box) return;
  try { pzSftChatQuitarArmando(); } catch (e) {}
  const total = (pend && pend.items) ? pend.items.length : 0;
  const n = (pend && typeof pend.idx === 'number') ? pend.idx + 1 : 1;
  const texto = total > 1
    ? (en ? '⏳ Putting together your post… (' + n + ' of ' + total + ') — usually under a minute.' : '⏳ Armando tu posteo… (' + n + ' de ' + total + ') — suele tardar menos de un minuto.')
    : (en ? '⏳ Putting together your post… — usually under a minute.' : '⏳ Armando tu posteo… — suele tardar menos de un minuto.');
  const div = document.createElement('div');
  div.className = 'chat-msg ai'; div.id = 'pzSftArmando';
  div.innerHTML = '<div style="font-size:13px;color:var(--mut)">' + esc(texto) + '</div>';
  box.appendChild(div);
  try { chatScroll(); } catch (e) {}
}
function pzSftChatQuitarArmando() {
  try { const d = document.getElementById('pzSftArmando'); if (d) d.remove(); } catch (e) {}
}
// (LOTE FOTOS-VIDEOS v860 · opción 5) La semana de una vez: una sola
// pantalla con una fila por posteo armado + «Aprobar toda la semana».
// Las filas se agregan a medida que se arma cada foto/video (la cadena
// arma en orden, en huecos consecutivos). Tocás una fila para cambiar
// ese posteo (abre su tarjeta, opción 3). Sin botón muerto «tocar uno
// para cambiarlo»: las filas son tocables y la nota lo dice.
function pzSftChatSemanaAgregar(prop) {
  const en = pzSftEn();
  const box = document.getElementById('chatBox');
  if (!box) return;
  try { pzSftChatQuitarArmando(); } catch (e) {}
  const pid = Number(prop.postId) || 0;
  PZ_SFT_ARMADOS[pid] = prop;
  let screen = document.getElementById('pzSftSemana');
  if (!screen) {
    const pend = PZ_SFT_CHAT_PENDIENTE;
    const total = (pend && pend.items) ? pend.items.length : 0;
    const wrap = document.createElement('div');
    wrap.className = 'chat-msg ai'; wrap.id = 'pzSftSemana'; wrap.style.maxWidth = '100%';
    wrap.innerHTML = '<div style="font-weight:700;font-size:13px;margin-bottom:4px">' + esc(en ? ('Perfect! I put together the week with all ' + total + ' 👇') : ('¡Perfecto! Te armé la semana con las ' + total + ' 👇')) + '</div>'
      + '<div style="font-size:12px;color:var(--mut);margin-bottom:8px">' + esc(en ? 'Nothing goes out until you approve — tap a row to change that post.' : 'Nada sale hasta que apruebes — tocá una fila para cambiar ese posteo.') + '</div>'
      + '<div id="pzSftSemanaRows"></div>'
      + '<div id="pzSftSemanaBtns" style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button type="button" class="btn btn-sm" style="background:#22C55E;color:#fff;border:none;box-shadow:0 6px 16px rgba(34,197,94,.42);flex:1 1 100%" onclick="pzSftChatAprobarTodas()">' + esc(en ? 'Approve the whole week ✓' : 'Aprobar toda la semana ✓') + '</button></div>';
    box.appendChild(wrap);
    screen = wrap;
    try { chatScroll(); } catch (e) {}
  }
  const rows = document.getElementById('pzSftSemanaRows');
  if (!rows) return;
  const old = document.getElementById('pzSftSemanaRow-' + pid);
  if (old) old.remove();
  rows.insertAdjacentHTML('beforeend', pzSftChatSemanaFilaHtml(prop));
  try { chatScroll(); } catch (e) {}
}
function pzSftChatSemanaFilaHtml(prop) {
  const en = pzSftEn();
  const pid = Number(prop.postId) || 0;
  const esVideo = prop.kind === 'video';
  const thumb = esVideo
    ? (prop.thumb ? `<img src="${esc(prop.thumb)}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block">` : (prop.image_path ? `<video src="${esc(prop.image_path)}" muted playsinline preload="metadata" style="width:100%;height:100%;object-fit:cover;display:block"></video>` : ''))
    : (prop.image_path ? `<img src="${esc(prop.image_path)}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block">` : '');
  const diaCorto = String(prop.dia_label || '').split(' ')[0] || '';
  const weekday = diaCorto ? diaCorto.toUpperCase() : (en ? 'TODAY' : 'HOY');
  const cap1 = String(prop.caption || '').split('\n')[0].trim();
  const metaDia = prop.dia_label ? esc(prop.dia_label) : (en ? 'Today' : 'Hoy');
  const meta = metaDia + (prop.hora ? ' · ' + esc(prop.hora) : '') + ' · ' + (esVideo ? 'Reel' : 'Post');
  return `<div class="pz-sft-semana-row" id="pzSftSemanaRow-${pid}" onclick="pzSftChatSemanaAbrir(${pid})" role="button" tabindex="0" style="display:flex;gap:11px;border:1px solid #e3e8ee;border-radius:14px;padding:10px;margin-bottom:10px;background:#fff;align-items:center;cursor:pointer"><div style="width:64px;height:80px;flex:0 0 64px;border-radius:10px;overflow:hidden;position:relative;border:1px solid #e3e8ee">${thumb}${esVideo ? '<span style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:26px;height:26px;border-radius:50%;background:rgba(10,30,51,.72);border:2px solid #fff;color:#fff;display:flex;align-items:center;justify-content:center;font-size:11px;padding-left:2px">▶</span>' : ''}</div><div style="flex:1;min-width:0"><div style="font-size:12px;font-weight:800;color:#2793C8;letter-spacing:.4px">${esc(weekday)}</div><div style="font-size:13.5px;line-height:1.35;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(cap1)}</div><div style="font-size:12.5px;color:var(--mut);margin-top:3px;font-weight:600">${meta}</div></div><div style="color:var(--mut);font-size:18px">›</div></div>`;
}
function pzSftChatSemanaAbrir(postId) {
  const prop = (postId && PZ_SFT_ARMADOS[Number(postId)]) || null;
  if (!prop) return;
  try { pzSftChatTarjetaArmada(prop); } catch (e) {}
}
// (LOTE FOTOS-VIDEOS v860 · #5) Descartar una propuesta: borra el
// borrador (POST /descartar-propuesta) y la foto queda como material.
// Quita la tarjeta y la fila de la semana; si no quedan filas, quita
// la pantalla semana; si todos los ítems están decididos, limpia el
// pendiente. Si el borrador ya no es descartable (409), igual se quita
// la tarjeta: la propuesta ya no existe como tal.
async function pzSftChatDescartar(postId) {
  const pid = Number(postId) || 0;
  if (!pid) return;
  const en = pzSftEn();
  const pend = PZ_SFT_CHAT_PENDIENTE;
  try {
    await api.post('/api/posts/' + pid + '/descartar-propuesta', {});
  } catch (e) {}
  try {
    const card = document.getElementById('pzSftCard-' + pid);
    if (card) card.remove();
    const row = document.getElementById('pzSftSemanaRow-' + pid);
    if (row) row.remove();
    const rows = document.getElementById('pzSftSemanaRows');
    if (rows && !rows.children.length) {
      const screen = document.getElementById('pzSftSemana');
      if (screen) screen.remove();
    }
    const propBorrada = (typeof PZ_SFT_ARMADOS !== 'undefined') ? PZ_SFT_ARMADOS[pid] : null;
    if (typeof PZ_SFT_ARMADOS !== 'undefined' && PZ_SFT_ARMADOS[pid]) delete PZ_SFT_ARMADOS[pid];
    if (pend && pend.items) {
      const it = pend.items.find((x) => x && propBorrada && Number(x.assetId) === Number(propBorrada.assetId));
      if (it) it.choice = 'descartado';
      const decidido = (x) => x.choice === 'armar' || x.choice === 'expres' || x.choice === 'descartado' || x.choice === 'despues';
      if (pend.items.every(decidido)) PZ_SFT_CHAT_PENDIENTE = null;
    }
    try { toast(en ? 'Discarded — the photo stays saved as material.' : 'Descartado — la foto queda guardada como material.'); } catch (e) {}
  } catch (e) {}
}
// (LOTE FOTOS-VIDEOS v860) El video no se cambia con usar-foto (solo
// fotos): el chip 🎬 avisa honesto cómo cambiarlo.
function pzSftChatVideoAviso() {
  try { toast(pzSftEn() ? 'To change the video, send another one in the chat 📷' : 'Para cambiar el video, mandá otro por el chat 📷'); } catch (e) {}
}

// (v846 · CHAT SOLO POR AUDIO) «Cambiar texto» murió con su editor:
// el cambio se pide por voz con [Cambiar algo] (pzCambioVoz).
/* (LOTE CHAT-CLICKS · punto 2) «Cambiar día»: píldoras de días libres
   SIN salir del chat (antes navegaba al detalle del posteo). */
async function pzSftChatCambiarDia(postId) {
  const prop = (postId && PZ_SFT_ARMADOS[Number(postId)]) || PZ_SFT_ARMADO_ACTUAL;
  if (!prop || !prop.postId) return;
  const en = pzSftEn();
  const slot = document.getElementById('pzSftDias-' + Number(prop.postId));
  if (!slot) return;
  if (slot.dataset.open === '1') { slot.innerHTML = ''; slot.dataset.open = ''; return; }
  slot.dataset.open = '1';
  slot.innerHTML = '<div style="font-size:12px;color:var(--mut);padding:6px 2px">' + esc(en ? 'Looking for free days…' : 'Buscando días libres…') + '</div>';
  try {
    const d = await api.get('/api/posts/dias-libres?kind=' + encodeURIComponent(prop.kind === 'video' ? 'video' : 'photo') + '&post_id=' + Number(prop.postId) + '&n=7');
    if (!d || !d.ok || !Array.isArray(d.dias) || !d.dias.length) {
      slot.innerHTML = '<div style="font-size:12px;color:var(--mut);padding:6px 2px">' + esc(en ? 'No free days right now.' : 'No hay días libres por ahora.') + '</div>';
      return;
    }
    let html = '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">';
    for (const dia of d.dias) {
      html += '<button type="button" class="chat-cap-opt" onclick="pzSftChatMoverDia(' + Number(prop.postId) + ', \'' + String(dia.iso).replace(/'/g, '') + '\', \'' + String(dia.dia || '').replace(/'/g, '') + '\', \'' + String(dia.dia_label || '').replace(/'/g, '') + '\', \'' + String(dia.hora || '').replace(/'/g, '') + '\')"><b>' + esc(dia.dia_label || dia.dia) + '</b><span>' + esc(dia.hora || '') + '</span></button>';
    }
    html += '<button type="button" class="chat-cap-opt" onclick="pzSftChatCambiarDia(' + Number(prop.postId) + ')"><b>' + esc(en ? 'Cancel' : 'Cancelar') + '</b><span></span></button></div>';
    slot.innerHTML = html;
    // (LOTE FOTOS-VIDEOS v860) La hora también se cambia acá: mismo día,
    // otra hora (09:00–21:00, GET /horas-libres). Si el endpoint falla,
    // quedan solo los días — nunca se rompe el panel.
    try {
      const diaActual = String(prop.dia || '');
      if (diaActual) {
        const h = await api.get('/api/posts/' + Number(prop.postId) + '/horas-libres?dia=' + encodeURIComponent(diaActual));
        if (h && h.ok && Array.isArray(h.horas) && h.horas.length) {
          let hh = '<div style="font-size:12px;color:var(--mut);padding:8px 2px 2px">' + esc(en ? 'Time' : 'Hora') + '</div><div style="display:flex;gap:8px;flex-wrap:wrap">';
          for (const ho of h.horas) {
            hh += '<button type="button" class="chat-cap-opt" onclick="pzSftChatMoverDia(' + Number(prop.postId) + ', \'' + String(ho.iso).replace(/'/g, '') + '\', \'' + String(diaActual).replace(/'/g, '') + '\', \'' + String(prop.dia_label || '').replace(/'/g, '') + '\', \'' + String(ho.hora || '').replace(/'/g, '') + '\')"><b>' + esc(ho.hora || '') + '</b><span></span></button>';
          }
          hh += '</div>';
          slot.innerHTML += hh;
        }
      }
    } catch (e) {}
  } catch (e) {
    slot.innerHTML = '<div style="font-size:12px;color:var(--mut);padding:6px 2px">' + esc(en ? 'I could not load the free days.' : 'No pude cargar los días libres.') + '</div>';
  }
}
async function pzSftChatMoverDia(postId, iso, dia, diaLabel, hora) {
  const prop = (postId && PZ_SFT_ARMADOS[Number(postId)]) || PZ_SFT_ARMADO_ACTUAL;
  if (!prop || !prop.postId) return;
  const en = pzSftEn();
  try {
    const d = await api.patch('/api/posts/' + encodeURIComponent(prop.postId), { action: 'save-draft', scheduled_at: iso });
    if (!d || !d.ok) throw new Error((d && d.message) || (d && d.error) || 'fail');
    prop.scheduled_at = (d && d.scheduled_at) || iso;
    prop.dia = dia || prop.dia;
    prop.dia_label = diaLabel || prop.dia_label;
    prop.hora = hora || prop.hora;
    const card = document.getElementById('pzSftCard-' + Number(prop.postId));
    if (card) { const cu = card.querySelector('.pz-sft-cuando'); if (cu) cu.innerHTML = '<b>' + esc(en ? ('Goes out ' + prop.dia_label + ' at ' + prop.hora) : ('Sale el ' + prop.dia_label + ' a las ' + prop.hora)) + '</b>'; }
    // (LOTE FOTOS-VIDEOS v860) El chip 📅 es lo que se ve: se actualiza con el nuevo día·hora.
    try { const chip = document.getElementById('pzSftChipCuando-' + Number(prop.postId)); if (chip) chip.textContent = '📅 ' + (prop.dia_label || '') + ' · ' + (prop.hora || ''); } catch (e) {}
    const slot = document.getElementById('pzSftDias-' + Number(prop.postId));
    if (slot) { slot.innerHTML = ''; slot.dataset.open = ''; }
    toast('🗓️ ' + (en ? ('Rescheduled — goes out ' + prop.dia_label + ' at ' + prop.hora) : ('Reprogramado — sale el ' + prop.dia_label + ' a las ' + prop.hora)));
    try { render(); } catch (e) {}
  } catch (e) {
    toast('😅 ' + esc((e && e.message) || (en ? 'Try again' : 'Probá de nuevo')));
  }
}
/* (LOTE CHAT-CLICKS · punto 2) «Otra foto»: cicla las fotos LIBRES del
   cliente (nunca regenera IA). El fetch es fresco por tap: la foto
   vieja vuelve a ser libre tras el reemplazo y puede volver en el
   ciclo. La tarjeta ES la vista previa — nada se publica hasta
   «Sale así» — así que el cambio es directo, sin sheet de confirmación
   (el preview con confirmación sigue vigente en «Usar la foto que
   envié»). */
var PZ_OTRAFOTO_IDX = {}; // postId → índice del ciclo
async function pzSftChatOtraFoto(postId) {
  const prop = (postId && PZ_SFT_ARMADOS[Number(postId)]) || PZ_SFT_ARMADO_ACTUAL;
  if (!prop || !prop.postId) return;
  const en = pzSftEn();
  const pend = PZ_SFT_CHAT_PENDIENTE;
  const batchIds = new Set((pend && pend.items ? pend.items : []).map((x) => Number(x.assetId) || 0));
  try {
    const d = await api.get('/api/album/libres');
    if (!d || !d.ok) throw new Error('libres');
    const list = (Array.isArray(d.libres) ? d.libres : []).filter((f) => f && Number(f.id) && !batchIds.has(Number(f.id)) && Number(f.id) !== Number(prop.assetId || 0));
    if (!list.length) { toast(en ? 'You have no more free photos — upload one first.' : 'No tenés más fotos libres — subí una primero.'); return; }
    const pid = Number(prop.postId);
    let idx = PZ_OTRAFOTO_IDX[pid];
    if (!Number.isInteger(idx)) idx = -1;
    for (let tries = 0; tries < list.length; tries++) {
      idx = (idx + 1) % list.length;
      const cand = list[idx];
      try {
        const r = await api.post('/api/posts/' + encodeURIComponent(prop.postId) + '/usar-foto', { asset_id: Number(cand.id) });
        if (!r || !r.ok) {
          if (r && r.error === 'ocupada') continue;
          throw new Error((r && r.error) || 'fail');
        }
        PZ_OTRAFOTO_IDX[pid] = idx;
        prop.image_path = r.image_path || cand.path;
        prop.assetId = Number(cand.id);
        const card = document.getElementById('pzSftCard-' + pid);
        if (card) { const img = card.querySelector('.pz-sft-img'); if (img) img.src = prop.image_path; }
        toast('✅ ' + (en ? 'Photo changed' : 'Foto cambiada'));
        try { render(); } catch (e) {}
        return;
      } catch (e) {
        if (String((e && e.message) || '').indexOf('ocupada') >= 0) continue;
        throw e;
      }
    }
    toast(en ? 'You have no more free photos — upload one first.' : 'No tenés más fotos libres — subí una primero.');
  } catch (e) {
    toast('😅 ' + esc((e && e.message) || (en ? 'Try again' : 'Probá de nuevo')));
  }
}

// (LOTE A · «Usar la foto que envié», Valentino 8/11 21:10) Cuando Posty
// ofrece un posteo (detalle/aprobación y tarjeta armada del chat), el
// cliente puede cambiar la imagen por una foto que él ya envió, con un
// toque. Flujo: libres → candidata (miniatura + cuándo se envió) →
// preview del posteo con esa foto → Confirmar. Nunca reemplazo en
// silencio: sin el toque del cliente, la foto del posteo no cambia.
// «La última foto» = la más reciente todavía libre (sin posteo
// asignado); si la última ya tiene su posteo, se avisa y se ofrecen
// las anteriores libres.
var PZ_USARFOTO_EL = null;
function pzUsarFotoCerrar() { try { if (PZ_USARFOTO_EL) PZ_USARFOTO_EL.remove(); } catch (e) {} PZ_USARFOTO_EL = null; }
async function pzUsarFotoAbrir(postId) {
  if (!postId) return;
  const en = (typeof ME !== 'undefined' && ME && ME.lang === 'en');
  pzUsarFotoCerrar();
  const el = document.createElement('div');
  el.className = 'pz-usarfoto-sheet';
  el.innerHTML = '<div class="pz-usarfoto-card"><h4>' + esc(en ? 'Use a photo you sent' : 'Usar la foto que envié') + '</h4><p class="pz-usarfoto-sub">' + esc(en ? 'Pick the photo — you will see the post with it before anything changes.' : 'Elegí la foto — vas a ver el posteo con esa foto antes de que cambie nada.') + '</p><div class="pz-usarfoto-list"><p>' + esc(en ? 'Loading your photos…' : 'Buscando tus fotos…') + '</p></div><button type="button" class="btn btn-ghost" onclick="pzUsarFotoCerrar()">' + esc(en ? 'Cancel' : 'Cancelar') + '</button></div>';
  document.body.appendChild(el);
  PZ_USARFOTO_EL = el;
  try {
    const d = await api.get('/api/album/libres');
    const list = el.querySelector('.pz-usarfoto-list');
    if (!list) return;
    if (!d || !d.ok) { list.innerHTML = '<p>' + esc(en ? 'I could not load your photos.' : 'No pude cargar tus fotos.') + '</p>'; return; }
    const libres = Array.isArray(d.libres) ? d.libres : [];
    let html = '';
    if (d.ultima_ocupada && d.ultima_ocupada.dia_label) html += '<p class="pz-usarfoto-note">' + esc(en ? ('The last photo you sent already has its post for ' + d.ultima_ocupada.dia_label + ' — here are the previous free ones.') : ('La última foto que mandaste ya tiene su posteo para el ' + d.ultima_ocupada.dia_label + ' — estas son las anteriores libres.')) + '</p>';
    if (!libres.length) { html += '<p>' + esc(en ? 'You have no free photos — upload one first.' : 'No tenés fotos libres — subí una primero.') + '</p>'; }
    for (const f of libres) {
      html += '<button type="button" class="pz-usarfoto-opt" onclick="pzUsarFotoPreview(' + Number(postId) + ',' + Number(f.id) + ')"><img src="' + esc(f.thumb || f.path) + '" alt="" loading="lazy"><span>' + esc(en ? ('sent ' + (f.cuando || '')) : ('la mandaste ' + (f.cuando || ''))) + '</span></button>';
    }
    list.innerHTML = html;
  } catch (e) {
    const list = el.querySelector('.pz-usarfoto-list');
    if (list) list.innerHTML = '<p>' + esc(en ? 'I could not load your photos.' : 'No pude cargar tus fotos.') + '</p>';
  }
}
async function pzUsarFotoPreview(postId, assetId) {
  const en = (typeof ME !== 'undefined' && ME && ME.lang === 'en');
  const el = PZ_USARFOTO_EL;
  if (!el) return;
  const list = el.querySelector('.pz-usarfoto-list');
  if (list) list.innerHTML = '<p>' + esc(en ? 'Loading the preview…' : 'Cargando la vista previa…') + '</p>';
  try {
    const d = await api.post('/api/posts/' + encodeURIComponent(postId) + '/usar-foto', { asset_id: assetId, preview: true });
    if (!list) return;
    if (!d || !d.ok) {
      if (d && d.error === 'ocupada') { list.innerHTML = '<p>' + esc(en ? ('That photo already has its post for ' + (d.dia_label || '') + '. Pick another one.') : ('Esa foto ya tiene su posteo para el ' + (d.dia_label || '') + '. Elegí otra.')) + '</p>'; return; }
      throw new Error((d && d.error) || 'fail');
    }
    list.innerHTML = '<div class="pz-usarfoto-prev"><img src="' + esc(d.thumb || d.image_path) + '" alt="" style="width:100%;border-radius:12px;display:block"><p>' + esc(en ? ('You sent it ' + (d.cuando || '') + '.') : ('La mandaste ' + (d.cuando || '') + '.')) + '</p>' + (d.caption ? '<p style="font-size:13px">' + esc(d.caption) + '</p>' : '') + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><button type="button" class="btn btn-primary btn-sm" onclick="pzUsarFotoConfirmar(' + Number(postId) + ',' + Number(assetId) + ')">' + esc(en ? 'Confirm change' : 'Confirmar cambio') + '</button><button type="button" class="btn btn-ghost btn-sm" onclick="pzUsarFotoAbrir(' + Number(postId) + ')">' + esc(en ? 'Back' : 'Volver') + '</button></div></div>';
  } catch (e) {
    if (list) list.innerHTML = '<p>' + esc(en ? 'I could not load the preview.' : 'No pude cargar la vista previa.') + '</p>';
  }
}
async function pzUsarFotoConfirmar(postId, assetId) {
  const en = (typeof ME !== 'undefined' && ME && ME.lang === 'en');
  try {
    const d = await api.post('/api/posts/' + encodeURIComponent(postId) + '/usar-foto', { asset_id: assetId });
    if (!d || !d.ok) throw new Error((d && d.error) || 'fail');
    pzUsarFotoCerrar();
    toast('✅ ' + (en ? 'Photo changed' : 'Foto cambiada'));
    try { render(); } catch (e) {}
  } catch (e) {
    toast('😅 ' + esc((e && e.message) || (en ? 'Try again' : 'Probá de nuevo')));
  }
}

/* Las 3 opciones viejas, accesibles desde la propuesta (y desde el
   Álbum, como antes): abre la pantalla elegir con las fotos pendientes.
   Si hay gate duro, abre directo la propuesta para resolverlo. */
function pzSftChatOpciones(irAPropuesta) {
  const pend = PZ_SFT_CHAT_PENDIENTE;
  if (!pend) return;
  const items = pend.items.map((x) => ({ assetId: x.assetId || 0, mediaId: x.mediaId || 0, kind: x.kind, url: x.url, thumb: x.thumb, tag: x.tag || "", issues: x.issues || [], choice: "", vision: x.vision || "", origen: "chat", file: x.file || null, duplicada: !!x.duplicada }));
  pzSftChatQuitarBotones();
  PZ_SFT_CHAT_PENDIENTE = null;
  pzSftAbrir(items, { origen: "chat", defVal: "preguntar" });
  if (irAPropuesta && PZ_SFT) { const first = PZ_SFT.items[0]; if (first) pzSftIrAPropuesta(first); }
}
/* Decido después sigue: la foto queda en el Álbum pendiente, sin
   posteo, y la cola de propuestas sigue con la foto siguiente. */
async function pzSftChatDespues() {
  const pend = PZ_SFT_CHAT_PENDIENTE;
  if (!pend) return;
  const it = pend.items[pend.idx];
  const en = pzSftEn();
  pzSftChatQuitarBotones();
  try {
    if (it.assetId) { try { await api.post("/api/album/" + it.assetId + "/choice", { choice: "despues" }); } catch (e) {} }
    else if (it.file && (await pzSftAsegurarAssetTmp(it))) { try { await api.post("/api/album/" + it.assetId + "/choice", { choice: "despues" }); } catch (e) {} }
  } catch (e) {}
  // (LOTE FOTOS-VIDEOS v860 · #5) Si este ítem ya tenía un borrador armado
  // (propuesta), se borra: «Decido después» no deja un posteo fantasma.
  try {
    const armadoD = (typeof PZ_SFT_ARMADOS !== 'undefined') ? Object.values(PZ_SFT_ARMADOS).find((p) => p && Number(p.assetId) === Number(it.assetId)) : null;
    if (armadoD && armadoD.postId) { try { await api.post('/api/posts/' + Number(armadoD.postId) + '/descartar-propuesta', {}); } catch (e) {} delete PZ_SFT_ARMADOS[Number(armadoD.postId)]; }
  } catch (e) {}
  it.choice = "despues";
  pzSftToast(en ? "Left in Pending, with no post." : "Quedó en Pendientes, sin posteo.");
  pend.idx++;
  pend.propuesta = null;
  if (pend.idx < pend.items.length) pzSftChatProponer();
  else PZ_SFT_CHAT_PENDIENTE = null;
}
/* Hook desde chatSend: si hay una foto pendiente y el usuario escribió
   algo de verdad, ese texto ES la instrucción (visión/feedback). No
   bloquea el chat normal: sin pendiente, no hace nada. Ignora el texto
   automático de foto sola y los diagnósticos. */
function pzSftChatTexto(sendText) {
  const pend = PZ_SFT_CHAT_PENDIENTE;
  if (!pend) return;
  const t = String(sendText || "").trim();
  if (!t) return;
  if (t.indexOf("📷 Te mando") === 0) return;
  if (/^diagn[oó]stico/i.test(t)) return;
  pend.texto = t;
  const it = pend.items[pend.idx];
  if (it) it.vision = t;
  if (pend.propuesta) { pzSftChatQuitarBotones(); pend.propuesta = null; pzSftChatProponer(); }
  else if (PZ_SFT_PREGUNTA_ACTIVA) { // respondió la pregunta escribiendo: la visión es su texto
    try { const w = document.getElementById('pzSftPregunta'); if (w) w.remove(); } catch (e) {}
    PZ_SFT_PREGUNTA_ACTIVA = null;
    pzSftChatProponer();
  }
}
/* REDEFINE el cierre del lote original: además del Álbum, cerrar la
   pantalla sin elegir marca las fotos de origen chat como «despues»
   (misma regla: si te vas sin elegir, quedan en Pendientes, sin
   posteo). El resto del comportamiento es idéntico al original. */
function pzSftCerrar() {
  if (!PZ_SFT) return;
  const st = PZ_SFT;
  const onDone = st.onDone;
  if (st.origen === "album" || st.origen === "chat") {
    st.items.forEach((it) => {
      if (!it.choice && !it.quitada && it.assetId) { try { api.post("/api/album/" + it.assetId + "/choice", { choice: "despues" }).catch(() => {}); } catch (e) {} }
    });
  }
  try { const ov = document.getElementById("pzSftOverlay"); if (ov) ov.remove(); } catch (e) {}
  PZ_SFT = null;
  try { if (onDone) onDone(); } catch (e) {}
}
